package org.traccar.tollpricing;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.locationtech.jts.geom.Envelope;
import org.locationtech.jts.index.strtree.STRtree;

import java.io.IOException;
import java.io.InputStream;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * A flat-rate facility's toll points: every rate-card plaza with the clustered map locations that
 * charge it (generated by {@code build_cfx_plazas.py}), joined to the card's rate for the fleet's
 * vehicle class and payment method. Plazas with no location are kept out of the index and listed,
 * so a passage there is missed (estimate low), never invented.
 */
public final class GantrySet {

    /** One clustered map location of a plaza. */
    public record Point(String facilityId, String plaza, double lat, double lon, BigDecimal rate) {
    }

    private final String facilityId;
    private final String currency;
    private final String cardValidFrom;
    private final String osmBase;
    private final List<Point> points = new ArrayList<>();
    private final List<String> unlocated = new ArrayList<>();
    private final List<String> excludedRamps = new ArrayList<>();
    private final STRtree index = new STRtree();
    private final Envelope extent = new Envelope();

    private GantrySet(String facilityId, String currency, String cardValidFrom, String osmBase) {
        this.facilityId = facilityId;
        this.currency = currency;
        this.cardValidFrom = cardValidFrom;
        this.osmBase = osmBase;
    }

    /**
     * @param vehicleColumn card column for the vehicle class, e.g. {@code "2_axle"}
     * @param paymentColumn card column for the payment method, e.g. {@code "pay_by_plate"}
     */
    /**
     * @param includeRamps whether ramp plazas are detected by trail distance. False for CFX: half of
     *                     its ramp booths lie within 50 m of the mainline, so distance alone would charge
     *                     through traffic at every interchange. Excluded ramps make the estimate low.
     */
    public static GantrySet load(String facilityId, InputStream card, InputStream gantries,
                                 String paymentColumn, String vehicleColumn, boolean includeRamps)
            throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        JsonNode c = mapper.readTree(card);
        JsonNode g = mapper.readTree(gantries);
        if (!"flat".equals(c.path("rate_model_type").asText())) {
            throw new IOException(facilityId + ": not a flat card");
        }
        if (!c.path("valid_from").asText().equals(g.path("card_valid_from").asText())) {
            throw new IOException(facilityId + ": gantry file was built against a different card ("
                    + g.path("card_valid_from").asText() + " vs " + c.path("valid_from").asText() + ")");
        }
        Map<String, BigDecimal> rates = new HashMap<>();
        for (JsonNode p : c.path("plazas")) {
            JsonNode rate = p.path(paymentColumn).path(vehicleColumn);
            if (!rate.isNumber()) {
                throw new IOException(facilityId + ": no " + paymentColumn + "/" + vehicleColumn
                        + " rate for " + p.path("name").asText());
            }
            rates.put(p.path("road").asText() + "|" + p.path("name").asText(), rate.decimalValue());
        }
        GantrySet set = new GantrySet(facilityId, c.path("currency").asText(), c.path("valid_from").asText(),
                g.path("osm_base").asText(null));
        for (JsonNode p : g.path("plazas")) {
            String key = p.path("road").asText() + "|" + p.path("name").asText();
            BigDecimal rate = rates.get(key);
            if (rate == null) {
                throw new IOException(facilityId + ": gantry plaza not on card: " + key);
            }
            if (p.path("clusters").isEmpty()) {
                set.unlocated.add(key);
            }
            if (!includeRamps && "ramp".equals(p.path("plaza_type").asText())) {
                set.excludedRamps.add(key);
                continue;
            }
            for (JsonNode cl : p.path("clusters")) {
                Point point = new Point(facilityId, key, cl.path("lat").asDouble(), cl.path("lon").asDouble(), rate);
                set.points.add(point);
                Envelope e = new Envelope(point.lon(), point.lon(), point.lat(), point.lat());
                set.index.insert(e, point);
                set.extent.expandToInclude(e);
            }
        }
        set.index.build();
        return set;
    }

    @SuppressWarnings("unchecked")
    List<Point> query(Envelope envelope) {
        return index.query(envelope);
    }

    /** True when the position lies within {@code marginDeg} of this facility's toll points. */
    public boolean near(double lat, double lon, double marginDeg) {
        Envelope e = new Envelope(extent);
        e.expandBy(marginDeg);
        return e.contains(lon, lat);
    }

    public String getFacilityId() {
        return facilityId;
    }

    public String getCurrency() {
        return currency;
    }

    public String getCardValidFrom() {
        return cardValidFrom;
    }

    public String getOsmBase() {
        return osmBase;
    }

    public List<Point> getPoints() {
        return points;
    }

    public List<String> getUnlocated() {
        return unlocated;
    }

    public List<String> getExcludedRamps() {
        return excludedRamps;
    }

    public boolean rampsExcluded() {
        return !excludedRamps.isEmpty();
    }
}
